void CView::roundActiveMob()
{
    if(m_aMob.isEmpty())
        return;

    if(nullptr == m_activeMob)
    {
        changeCurrentMob(m_aMob.front());
        return;
    }


    m_activeMob->clearSelect();
    int actIndex = m_aMob.indexOf(m_activeMob);
    if(actIndex == m_aMob.size()-1)
        actIndex = 0;
    else
        ++actIndex;

    changeCurrentMob(m_aMob[actIndex]);
}

void CView::undo_roundActiveMob()
{
    if(m_aMob.size() <1)
        return;

    if(m_aMob.size() == 1)
    {
        if(nullptr != m_activeMob)
            changeCurrentMob(nullptr);

        return;
    }

    m_activeMob->clearSelect();
    int actIndex = m_aMob.indexOf(m_activeMob);
    if(actIndex == 0)
        actIndex = m_aMob.size()-1;
    else
        --actIndex;

    changeCurrentMob(m_aMob[actIndex]);
}

void CView::execUnloadCommand()
{
    if(!m_pLand->isMprLoad() && m_activeMob == nullptr)
        return;

    if(m_activeMob == nullptr)
    {
        cancelPendingOperation();
        m_pUndoStack->clear();
        unloadLand();
        return;
    }

    cancelPendingOperation();
    m_pUndoStack->clear();
    unloadActiveMob();
}

void CView::iterateRoundMob()
{
    if(nullptr == m_activeMob)
        return;

    if(nullptr == m_pRoundForm)
    {
        QList<QString> arrMob;
        arrMob.append(m_activeMob->mobName());
        for(auto& mob: m_aMob)
        {
            if(mob == m_activeMob)
                continue;
            arrMob.append(mob->mobName());
        }
        m_pRoundForm = new CRoundMobForm(this);
        m_pRoundForm->initMobList(arrMob);
        m_pRoundForm->show();
        return;
    }
    m_pRoundForm->round();
}

void CView::applyRoundMob()
{
    if(nullptr == m_pRoundForm)
        return;

    QString newMobName = m_pRoundForm->selectedMob();
    delete m_pRoundForm;
    m_pRoundForm = nullptr;
    if (newMobName == m_activeMob->mobName())
        return;

    auto pChangeMobCommand = new CChangeActiveMobCommand(this, newMobName);
    m_pUndoStack->push(pChangeMobCommand);
}

void CView::saveSession()
{
    if(!m_pLand->isMprLoad())
        return;

    QString mprPath(m_pLand->filePath().absoluteFilePath());
    QVector<QString> arrMobPath;

    for(auto& mob: m_aMob)
    {
        if(mob == m_activeMob)
            continue;
        arrMobPath.append(mob->filePath().absoluteFilePath());
    }
    if(m_activeMob)
        arrMobPath.append(m_activeMob->filePath().absoluteFilePath());

    auto pManager = CSessionDataManager::getInstance();
    pManager->reset();
    pManager->addZoneData(mprPath, arrMobPath);
    pManager->addWorkspaceIdentity(m_sessionWorkspaceKind,
                                   m_sessionWorkspaceIdentifier,
                                   m_sessionWorkspaceDisplayName,
                                   m_sessionWorkspaceMapZoneId);
    QVector3D pos, pivot, rot;
    m_cam->getLocation(pos, pivot, rot);
    pManager->addCameraData(pos, pivot, rot);
    pManager->addQuickTileIndices(m_pTileForm->quickTileSet());
    pManager->saveSession();
}

void CView::loadSession()
{
    const QScopedValueRollback<int> projectionDepth(m_openingProjectionDepth,m_openingProjectionDepth+(property("rebuild64Selected").toBool()?1:0));
    auto pManager = CSessionDataManager::getInstance();
    pManager->reset();
    pManager->loadSession();
    pManager->getWorkspaceIdentity(m_sessionWorkspaceKind,
                                   m_sessionWorkspaceIdentifier,
                                   m_sessionWorkspaceDisplayName,
                                   m_sessionWorkspaceMapZoneId);

    QString mprPath;
    QVector<QString> arrMobPath;
    if(!pManager->getZoneData(mprPath, arrMobPath))
        return;

    if(mprPath.isEmpty())
        return;

    QFileInfo mprFile(mprPath);
    if(!mprFile.exists())
    {
        ei::log(eLogWarning, "Cannot find MPR file: " + mprFile.absoluteFilePath());
        return;
    }
    prepareDocumentTransition();
    m_pUndoStack->clear();
    QVector3D savedPos,savedPivot,savedRot;
    if(pManager->getCameraData(savedPos,savedPivot,savedRot))m_cam->setLocation(savedPos,savedPivot,savedRot);
    setProperty("rebuild64OpeningMobs",QStringList(arrMobPath.toList()));
    loadLandscape(mprFile);

    for(const auto& mobPath: arrMobPath)
    {
        QFileInfo mobFile(mobPath);
        if(!mobFile.exists())
        {
            ei::log(eLogWarning, "Cannot find MOB file: " + mobFile.absoluteFilePath());
            continue;
        }
        loadMob(mobFile);
        roundActiveMob();
    }

    QVector<int> arrQuickInd;
    if(pManager->getdQuickTileIndices(arrQuickInd))
    {
        m_pTileForm->setQuickTileSet(arrQuickInd);
    }
}

void CView::setSessionWorkspaceIdentity(const QString& kind, const QString& identifier,
                                        const QString& displayName, const QString& mapZoneId)
{
    m_sessionWorkspaceKind = kind;
    m_sessionWorkspaceIdentifier = identifier;
    m_sessionWorkspaceDisplayName = displayName;
    m_sessionWorkspaceMapZoneId = mapZoneId;
}

bool CView::isRecentAvailable()
{
    return m_recentOpenedFile_file.exists();
}

int CView::renameActiveMobUnits(QMap<QString, QString> &mapName)
{
    ei::log(ELogMessageType::eLogInfo, "processing map " + m_activeMob->mobName());
    int n=0;
    CUnit* pUnit = nullptr;
    QString sourceName;
    for(auto& node:m_activeMob->nodes())
    {
        if(node->nodeType() != ENodeType::eUnit)
            continue;
        pUnit = dynamic_cast<CUnit*>(node);
        sourceName = pUnit->databaseName();
        if(mapName.contains(sourceName))
        {
            QSharedPointer<IPropertyBase> newName(new propStr(eObjParam_UNIT_PROTOTYPE, mapName[sourceName]));
            pUnit->applyParam(newName);
            ++n;
            ei::log(eLogInfo, "Unit:" + QString::number(pUnit->mapId()) + " last name:" + sourceName + " new name:" + newName->toString());
        }
        else
            ei::log(ELogMessageType::eLogFatal, "not found:" + sourceName);
    }
    ei::log(ELogMessageType::eLogInfo, "processing map finished:" + m_activeMob->mobName());
    return n;
}

// Synthetic production-command regression. Never reads or writes game resources.
bool patrolAuthoringIntegrationCheck(CView* view)
{
    QSignalBlocker blocked(view);
    QSignalBlocker blockedScene(CScene::getInstance());
    const auto previousMode=CScene::getInstance()->getMode();
    CScene::getInstance()->changeMode(eEditModeLogic);
    CMob* previousMob = view->m_activeMob;
    const int previousSlot = view->m_logicSlotIndex;
    CMob mob;
    CUnit* first = new CUnit;
    CUnit* second = new CUnit;
    first->setMapId(1398); second->setMapId(1398);
    mob.nodes().append(first); mob.nodes().append(second);
    view->m_activeMob = &mob; view->m_logicSlotIndex = 0;
    const auto snapshot = [](CLogic* logic) { QJsonObject data; logic->serializeJson(data); return data; };
    const auto guard = [](CUnit* unit) {
        QSharedPointer<IPropertyBase> value(new propUint(eObjParam_LOGIC_BEHAVIOUR, uint(eRadius)));
        unit->applyLogicParamAt(0, value);
    };
    for(CUnit* unit : {first, second}) {
        CLogic* logic = unit->logicAt(0);
        logic->setGuardPlacement(QVector3D(unit == first ? 10 : 90, 20, 3));
        for(int i=0;i<4;++i) logic->createPatrolByIndex(i-1);
        logic->createViewByIndex(0,-1);
        logic->patrolPoints()[2]->markAsDeleted(true);
        guard(unit);
    }
    // Exercise the actual Behavior combobox signal -> selection fanout -> undo command.
    {
        QUndoStack history;
        QUndoStack* previousHistory=view->m_pUndoStack;
        view->m_pUndoStack=&history;
        mob.logicNodesUpdate();
        mob.clearSelect(true);
        first->setState(eDraw); second->setState(eSelect);
        QJsonObject before=snapshot(second->logicAt(0));
        QSharedPointer<IPropertyBase> value(new propUint(eObjParam_LOGIC_BEHAVIOUR,uint(eRadius)));
        CComboStItem combo(value);
        QObject::connect(&combo,&CComboStItem::onParamChange,view,&CView::onParamChange);
        combo.setCurrentIndex(int(ePath));
        bool result=second->logicAt(0)->isBehaviourPath() && second->logicAt(0)->patrolPoints().isEmpty()
            && first->logicAt(0)->patrolPoints().size()==4 && history.count()==1;
        history.undo(); result=result && snapshot(second->logicAt(0))==before;
        history.redo(); result=result && second->logicAt(0)->patrolPoints().isEmpty();
        history.undo(); history.clear();
        first->setState(eDraw); second->setState(eDraw);
        combo.setCurrentIndex(int(eRadius));
        first->setState(eSelect); second->setState(eSelect);
        combo.setCurrentIndex(int(ePath));
        result=result && first->logicAt(0)->patrolPoints().isEmpty()
            && second->logicAt(0)->patrolPoints().isEmpty() && history.count()==1;
        history.undo(); history.clear();
        value.reset(new propUint(eObjParam_LOGIC_BEHAVIOUR,uint(ePath)));
        history.push(new CChangeLogicParam(view,second,value,nullptr,true));
        result=result && second->logicAt(0)->isBehaviourPath() && second->logicAt(0)->patrolPoints().size()==4;
        history.undo(); result=result && snapshot(second->logicAt(0))==before;
        history.clear();
        view->m_pUndoStack=previousHistory;
        if(!result) { fprintf(stderr,"Behavior combobox regression failed\n");
            view->m_activeMob=previousMob;view->m_logicSlotIndex=previousSlot;CScene::getInstance()->changeMode(previousMode);return false; }
    }
    const auto firstBefore = snapshot(first->logicAt(0));
    const auto secondBefore = snapshot(second->logicAt(0));
    const auto otherSlot = snapshot(second->logicAt(1));
    CPatrolPoint* retained = second->logicAt(0)->patrolPoints()[0];
    bool passed = true;
    const auto check = [&passed](bool condition, const char* label) {
        if(!condition) fprintf(stderr, "Patrol regression failed: %s\n", label);
        passed = passed && condition;
    };
    {
        QUndoStack history;
        auto* previousHistory=view->m_pUndoStack;
        const auto previousMobs=view->m_aMob;
        view->m_pUndoStack=&history;
        view->m_aMob={&mob};
        const QPoint cursor=view->rect().center();
        const QPoint moved=cursor+QPoint(30,20);
        QVector3D expected;
        const bool pick=view->objectPlacementPositionAt(moved,&expected);
        check(pick,"placement terrain/grid pick");
        for(bool group : {false,true}) {
            mob.clearSelect(true);
            first->setState(group ? eSelect : eDraw);second->setState(eSelect);
            view->addLogicPoint(false);
            check(view->isLogicPlacementPending(),"placement transaction starts");
            QMouseEvent move(QEvent::MouseMove,moved,Qt::NoButton,Qt::NoButton,Qt::NoModifier);
            view->m_pOp->mouseMoveEvent(&move);
            check(!pick || (second->logicAt(0)->patrolPoints()[0]->position()-expected).length()<0.001f,
                  "point under pointer without owner offset");
            if(group) check(!pick || (first->logicAt(0)->patrolPoints()[0]->position()-expected).length()<0.001f,
                            "group point under pointer");
            QMouseEvent strayRelease(QEvent::MouseButtonRelease,moved,Qt::LeftButton,Qt::NoButton,Qt::NoModifier);
            view->m_pOp->mouseReleaseEvent(&strayRelease);
            check(view->isLogicPlacementPending(),"release without map press must not commit");
            QKeyEvent escape(QEvent::KeyPress,Qt::Key_Escape,Qt::NoModifier);
            QApplication::sendEvent(view,&escape);
            check(!view->isLogicPlacementPending() && !view->hasPendingOperation()
                  && snapshot(first->logicAt(0))==firstBefore && snapshot(second->logicAt(0))==secondBefore,
                  "Escape restores route and removes preview");
            check(second->nodeState()==eSelect && (!group || first->nodeState()==eSelect),
                  "Escape restores owners selection");
            view->addLogicPoint(false);
            QMouseEvent press(QEvent::MouseButtonPress,moved,Qt::LeftButton,Qt::LeftButton,Qt::NoModifier);
            view->m_pOp->mousePressEvent(&press);
            view->m_pOp->mouseReleaseEvent(&strayRelease);
            check(!view->isLogicPlacementPending() && !view->hasPendingOperation(),"map click commits placement");
            check(!pick || (second->logicAt(0)->patrolPoints()[0]->position()-expected).length()<0.001f,
                  "click position committed");
            const auto placed=snapshot(second->logicAt(0));
            // A look-point preview uses the same placement path, without moving its patrol parent.
            view->addLogicPoint(true);
            view->m_pOp->mouseMoveEvent(&move);
            QApplication::sendEvent(view,&escape);
            check(snapshot(second->logicAt(0))==placed && !view->hasPendingOperation(),
                  "look preview Escape preserves committed patrol");
            history.undo();
            check(snapshot(first->logicAt(0))==firstBefore && snapshot(second->logicAt(0))==secondBefore,
                  "placement undo atomic");
            history.redo();
            check(second->logicAt(0)->patrolPoints().size()==1,"placement redo");
            history.undo(); history.clear();
        }
        view->m_pUndoStack=previousHistory;view->m_aMob=previousMobs;
    }
    {
        CBehaviorCollectionWidget inactive(second,0);
        QLabel* label=inactive.findChild<QLabel*>("behaviorRouteState");
        check(label && !label->property("patrolRouteActive").toBool(), "inactive label");
    }
    {
        QUndoStack history;
        // Both owners have the same ID; the second must not mutate the first.
        history.push(new CCreatePatrolCommand(view,second,"1398.-1",{second}));
        check(snapshot(first->logicAt(0))==firstBefore
            && second->logicAt(0)->patrolPoints().size()==1
            && second->logicAt(0)->isBehaviourPath(), "case 1");
        CPatrolPoint* created=second->logicAt(0)->patrolPoints().value(0);
        if(created) {
            const QVector3D destination(92,24,0);
            QSharedPointer<IPropertyBase> pos(new prop3D(eObjParam_POSITION,destination));
            history.push(new CChangeLogicParam(view,created,pos));
            if(created->position()!=destination || snapshot(first->logicAt(0))!=firstBefore)
                fprintf(stderr,"Patrol moved to %f,%f,%f; first unchanged=%d\n",
                    created->position().x(),created->position().y(),created->position().z(),
                    int(snapshot(first->logicAt(0))==firstBefore));
            check(created->position()==destination && snapshot(first->logicAt(0))==firstBefore, "case 2");
        } else passed=false;
        history.setIndex(0);
        check(snapshot(second->logicAt(0))==secondBefore
            && second->logicAt(0)->patrolPoints().value(0)==retained, "case 3");
        history.setIndex(history.count());
        check(second->logicAt(0)->patrolPoints().size()==1
            && second->logicAt(0)->patrolPoints()[0]->position()==QVector3D(92,24,0), "case 4");
        // Patrol Z is projected by the existing path recalculation (zero without terrain).
        const auto fresh=snapshot(second->logicAt(0));
        CPatrolPoint* active=second->logicAt(0)->patrolPoints()[0];
        history.push(new CCreatePatrolCommand(view,active,"1398.0.-1",{active}));
        check(active->lookPoint().size()==1 && snapshot(first->logicAt(0))==firstBefore,
              "look owner with duplicate ID");
        history.undo();
        check(snapshot(second->logicAt(0))==fresh,"look undo");

        history.push(new CCreatePatrolCommand(view,second,"1398.-1",{second}));
        check(second->logicAt(0)->patrolPoints().size()==2
            && second->logicAt(0)->patrolPoints()[0]->position()==QVector3D(92,24,0), "case 5");
        history.undo(); check(snapshot(second->logicAt(0))==fresh, "case 6");
        history.setIndex(0); history.clear();
        // Multi-owner creation is one undoable action; switching the UI slot cannot retarget Undo.
        history.beginMacro("two creatures");
        history.push(new CCreatePatrolCommand(view,first,"1398.-1",{first,second}));
        history.push(new CCreatePatrolCommand(view,second,"1398.-1",{first,second}));
        history.endMacro();
        check(first->logicAt(0)->patrolPoints().size()==1
            && second->logicAt(0)->patrolPoints().size()==1, "case 7");
        view->m_logicSlotIndex=1;
        history.undo();
        check(snapshot(first->logicAt(0))==firstBefore
            && snapshot(second->logicAt(0))==secondBefore && snapshot(second->logicAt(1))==otherSlot, "case 8");
        history.redo();
        QJsonObject saved=snapshot(second->logicAt(0));
        CLogic loaded(second); loaded.deSerializeJson(saved);
        check(snapshot(&loaded)==saved, "case 9");
        // Clearing applied history releases only the detached old route.
        history.clear();
        check(second->logicAt(0)->patrolPoints().size()==1, "case 10");
    }
    view->m_activeMob=previousMob; view->m_logicSlotIndex=previousSlot;
    view->collectObjectTreeData(); view->viewParameters();
    CScene::getInstance()->changeMode(previousMode);
    return passed;
}

// Exercises the production adoption boundary, including its next MP save.
// All archive bytes and pixels are synthetic and live in an auto-removed directory.
bool terrainBaselineAnimationIntegrationCheck(CView* view)
{
    if(!view || view->m_pLand->isMprLoad()) return false;
    QSignalBlocker blocked(view);
    QTemporaryDir temporary;
    const auto archiveBytes = [](const QVector<SResArchiveNewMember>& members) {
        QByteArray empty(16, '\0'), bytes;
        qToLittleEndian<quint32>(0x019CE23C, reinterpret_cast<uchar*>(empty.data()));
        qToLittleEndian<quint32>(16, reinterpret_cast<uchar*>(empty.data()+8));
        CResArchiveDocument archive; QStringList errors;
        if(!archive.loadBytes(empty, "synthetic", &errors)
           || !archive.buildWithAppendedMembers(members, &bytes, &errors)) return QByteArray();
        return bytes;
    };
    const auto write = [](const QString& path, const QByteArray& bytes) {
        QFile file(path); return !bytes.isEmpty() && file.open(QIODevice::WriteOnly)
            && file.write(bytes)==bytes.size();
    };
    QByteArray mp; QDataStream stream(&mp,QIODevice::WriteOnly);
    stream.setByteOrder(QDataStream::LittleEndian);
    stream.setFloatingPointPrecision(QDataStream::SinglePrecision);
    stream << quint32(0xCE4AF672) << float(100) << quint32(1) << quint32(1)
           << quint32(1) << quint32(256) << quint32(64) << quint32(32)
           << quint16(0) << quint32(1);
    for(int i=0;i<64;++i) stream << qint32(i<32 ? 6 : 1);
    stream << quint16(0) << quint16(32);
    QByteArray sector; QDataStream sec(&sector,QIODevice::WriteOnly);
    sec.setByteOrder(QDataStream::LittleEndian);
    sec << quint32(0xCF4BF774) << quint8(0);
    sector.append(QByteArray(33*33*8+16*16*2,'\0'));
    const auto member=[](const QString& name, const QByteArray& payload) {
        SResArchiveNewMember result; result.name=name; result.payload=payload; return result;
    };
    const QByteArray mpr=archiveBytes({member("WaterBaseline.MP",mp),member("WaterBaseline000000.SEC",sector)});
    QVector<QImage> tiles;
    for(int i=0;i<64;++i) {
        QImage tile(32,32,QImage::Format_ARGB32);
        tile.fill(i<32 ? QColor(0,64+i*4,192) : QColor(100+i,60,0)); tiles.append(tile);
    }
    QString error;
    const QByteArray page=ei::encodeMmpDxt1(CTerrainVirtualAtlas::composePage(tiles,0,32),true,&error);
    for(int i=0;i<64;++i)
        if(!ei::decodeMmpDxt1AtlasTile(page,i,&tiles[i],&error)) return false;
    STerrainAtlasProfile profile;
    profile.mprNamespace="waterbaseline"; profile.atlasSlotCount=64;
    STerrainAtlasProfileFamily family; family.id=1; family.name="Synthetic";
    profile.families.append(family);
    for(int i=0;i<64;++i) {
        STerrainAtlasProfileSlot slot; slot.slot=i;
        slot.signature.northWest=slot.signature.northEast=slot.signature.southEast=slot.signature.southWest=1;
        profile.slotDefinitions.append(slot);
    }
    profile.normalizeMembership();
    profile.textureCount=1; profile.approved=true;
    profile.atlasPixelSha256=CTerrainAtlasProfileInference::pixelSha256(tiles);
    profile.provenance="synthetic-water-baseline-regression";
    const QByteArray res=archiveBytes({member("WaterBaseline000.mmp",page),
        member(CTerrainAtlasProfileStore::embeddedMemberName(profile.mprNamespace),profile.toBytes())});
    const QString mprPath=temporary.filePath("WaterBaseline.mpr");
    const QString resPath=temporary.filePath("HDPack_Terrain.res");
    if(!temporary.isValid() || !write(mprPath,mpr) || !write(resPath,res)) return false;
    view->makeCurrent();
    CTextureList::getInstance()->setMapLocalTerrainArchive(resPath);
    view->m_pLand->readMap(QFileInfo(mprPath),false);
    CValidationReport report;
    bool ok=view->m_pLand->isMprLoad() && view->m_mprDocument.loadBytes(mpr,mprPath,&report)
        && view->m_terrainEdit.load(view->m_mprDocument,&report);
    view->m_terrainEditAvailable=ok;
    view->m_mprAnimatedTiles=view->m_mprDocument.mapInfo().animatedTiles;
    view->m_mprAnimatedTiles[0].tileIndex=16; // pre-compaction editor cache
    const QString hash=QString::fromLatin1(QCryptographicHash::hash(mpr,QCryptographicHash::Sha256).toHex());
    ok=ok && view->adoptCompleteTerrainBaseline(QFileInfo(mprPath),hash,tiles,resPath,profile,false);
    CMprEditTransaction transaction; QByteArray saved; CMprDocument reopened;
    ok=ok && view->m_mprDocument.appendMapParametersEdit(100,view->m_mprMaterials,
            view->m_mprAnimatedTiles,&transaction,&report)
        && view->m_mprDocument.applyTransaction(transaction,&saved,&report)
        && reopened.loadBytes(saved,"second-save.mpr",&report)
        && reopened.mapInfo().animatedTiles.size()==1
        && reopened.mapInfo().animatedTiles[0].tileIndex==0
        && reopened.mapInfo().animatedTiles[0].frameCount==32
        && view->m_pLand->animTiles()[0].tileIndex==0;
    fprintf(stderr,"Terrain baseline animation repeat-save: %s %s\n",ok?"PASS":"FAIL",qPrintable(report.toText()));
    view->unloadLand(false);
    CTextureList::getInstance()->setMapLocalTerrainArchive(QString());
    view->doneCurrent();
    return ok;
}

// Detached adapter for the same131 material-source selection and exact resolver
// used above by the manual brush. No singleton, QWidget or live CView access.
bool ai::realizeAgentPaintSignature(PaintSources& s,CTerrainWorkingAtlas& atlas,
    CTerrainEditModel& terrain,const STerrainTransitionSignature& signature,
    int x,int y,quint32 seed,qint32 material,QMap<int,quint64>* usage,
    const QSet<int>& protectedSlots,CValidationReport* report)
{
    if(!s.reference.isEmpty() && s.referenceHash.isEmpty()) {
        report->add("ai.reference",EValidationSeverity::Error,"The terrain reference is unavailable");return false;
    }
    bool exact=false;atlas.catalog().selectForPaint(signature,x,y,seed,material,&exact);
    if(exact)return true;
    const int priorSlots=atlas.activeTileCount();
    if(!exact) {
        auto candidates=s.transitions.values(globalTransitionKey(signature));
        std::sort(candidates.begin(),candidates.end(),[](const STerrainGlobalTransitionSource& a,const STerrainGlobalTransitionSource& b){
            if(a.atlasIdentity!=b.atlasIdentity)return a.atlasIdentity<b.atlasIdentity;
            if(a.atlasPixelSha256!=b.atlasPixelSha256)return a.atlasPixelSha256<b.atlasPixelSha256;
            if(a.slot!=b.slot)return a.slot<b.slot;return a.mprNamespace.toCaseFolded()<b.mprNamespace.toCaseFolded();
        });
        if(!s.reference.isEmpty())preferNativeTerrainBank(&candidates,s.nameSpace);
        QString bank;QSet<QByteArray> imported;bool any=false;
        for(const auto& source:candidates) {
            if(!s.reference.isEmpty()&&!bank.isEmpty()&&bank.compare(source.mprNamespace,Qt::CaseInsensitive)!=0)continue;
            const auto pixels=loadGlobalTransitionTile(source,atlas.synthesisTileSize(),&s.bindings,&s.missing,&s.tiles,nullptr,&s);
            if(pixels.isNull())continue;
            if(!s.reference.isEmpty())bank=source.mprNamespace;
            const auto identity=globalTransitionKey(source.signature)+terrainTilePixelSha256(pixels);
            if(imported.contains(identity))continue;imported.insert(identity);
            if(atlas.addAuthoredLibraryTransition(source.signature,pixels,source.mprNamespace,report,source.mprNamespace,source.slot))any=true;
        }
        if(any&&!atlas.realizeAuthoredLibraryVariants(signature,usage,protectedSlots,report,material))return false;
    }
    atlas.catalog().selectForPaint(signature,x,y,seed,material,&exact);
    if(!exact)for(qint32 id:QSet<qint32>{signature.northWest,signature.northEast,signature.southEast,signature.southWest}) {
        if(atlas.hasMaterialSource(id))continue;
        bool ready=false;
        for(const auto& family:s.families)if(family.id==id) {
            const auto pixels=loadBoundGlobalUniformSource(family,s.nameSpace,atlas.synthesisTileSize(),&s.bindings,&s.missing,&s.uniforms,nullptr,&s);
            ready=!pixels.isNull()&&atlas.addExternalMaterialSource(id,pixels);break;
        }
        if(!ready){report->add("ai.material",EValidationSeverity::Error,QString("No approved artwork for material %1").arg(id));return false;}
    }
    const auto packed=atlas.resolve(signature,x,y,usage,protectedSlots,nullptr,report,material);
    if(!report->hasErrors()&&usage) {
        // A whole region is resolved before its packed deltas are applied.
        // Reserve every newly realized variant for that region, otherwise a
        // later tuple could recycle the not-yet-painted earlier tuple.
        for(int slot=priorSlots;slot<atlas.activeTileCount();++slot)++(*usage)[slot];
        ++(*usage)[SMprPackedTile::decode(packed).atlasSlot()];
    }
    terrain.enableWorkingAtlasSlots(atlas.capacityLimit());
    return !report->hasErrors()&&terrain.installWorkingAtlasSlotTypes(atlas.activeTileTypes());
}
